mapper.select:
select IFNULL(sum(IFNULL(prac_trade_amount, 0)), 0)
from ${param.tableName}
where delflag_ = '1'
  and status in('6', '2','7','8')
  
      and created_time_ like #{param.year}
  
  
      and rel_info_list_str like #{param.relNumber}

SELECT IFNULL ( SUM (IFNULL(prac_trade_amount, 0)), 0 ) FROM ${param.tableName} WHERE consider_type IN ('1', '2') AND delflag_ != '0' AND prac_trade_amount IS NOT NULL
and created_time_ like #{param.year}
and rel_info_list_str like #{param.relNumber}
and not_major_rel_number like '%' || #{param.notClear} || '%'

SELECT IFNULL ( SUM (IFNULL(REL_TRADE_AMOUNT, 0)), 0 ) FROM ${param.tableName} WHERE consider_type IN ('2') AND prac_trade_amount IS NULL AND status = '6' AND delflag_ = '1'
and created_time_ like #{param.year}
and rel_info_list_str like #{param.relNumber}
and not_major_rel_number like '%' || #{param.notClear} || '%'

select IFNULL(sum(IFNULL(prac_trade_amount, 0)), 0)
from ins_tra_counterparty
where delflag_ = '1'
and status in('6', '2','7','8')
and REL_NUMBER = #{param.relNumber}

    and created_time_ like #{param.year}

        select IFNULL(sum(IFNULL(PRAC_TRADE_AMOUNT, 0)),0)
        from ins_tra_counterparty
        where delflag_ = '1'
        and status in('6', '2','7','8')

        
            and DATE_FORMAT(TRAN_DATE, '%Y')=#{param.year}
        

        
            and IS_ACCUMULATED = #{param.isAccumulated}
        
        
            and MAJOR_TRADE = #{param.majorTrade}
        
        
            and IS_TRADE_AGREEMENT = #{param.isTradeAgreement}
        

        
            and REL_NUMBER IN (
            SELECT unisc_code FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE unisc_code = #{param.relNumber}) )
        
        
            And REL_NUMBER = #{param.relNumber}
